create or replace function ml_private.stage4_resume_walk(s jsonb,path jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare probe jsonb:=jsonb_set(s,'{phase}','"moving"');prefix jsonb:='[]';cell text;a integer:=(s->>'active')::int;cost integer;begin
 for cell in select v#>>'{}' from ml_private.arr(path) v loop exit when not(ml_private.legal_steps(probe) ? cell);probe:=ml_private.stage3_collision(probe,cell);probe:=probe-'_pushedTasks';cost:=ml_private.classic_step_cost(probe,a,cell);probe:=jsonb_set(probe,'{movement,remaining}',to_jsonb((probe#>>'{movement,remaining}')::int-cost));probe:=jsonb_set(probe,array['players',a::text,'cell'],to_jsonb(cell));prefix:=prefix||jsonb_build_array(cell);if ml_private.stage4_location_stops(probe,a,cell) then probe:=jsonb_set(probe,'{movement,remaining}','0');end if;end loop;
 if jsonb_array_length(prefix)<>jsonb_array_length(path) then s:=ml_private.emit(s,'move','后续路径已变化，保留剩余步数');end if;return ml_private.classic_walk(s,prefix,at);
end $$;
create or replace function ml_private.stage4_reactive_arrival(s jsonb,a integer,origin text,cell text) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(ml_private.stage3_task('gear-react',jsonb_build_object('actor',v,'data',jsonb_build_object('root',coalesce(s#>'{cardStack,stack,0,serial}',to_jsonb(case when s->'movement'<>'null'::jsonb then 'move'||(s#>>'{movement,gearRoot}') else 'revision'||(s->>'revision') end))))) order by ord),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,ord)
 where coalesce(s->>'_gearReactiveSkip','false')<>'true' and coalesce(s#>>'{movement,gearQuiet}','false')<>'true' and ml_private.game_data(s,'map')#>>array[origin,'region']<>ml_private.game_data(s,'map')#>>array[cell,'region'] and (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and ml_private.game_data(s,'map')#>>array[s#>>array['players',v#>>'{}','cell'],'region']=ml_private.game_data(s,'map')#>>array[cell,'region'] and ml_private.stage4_combat_gear(s,(v#>>'{}')::int,'basic-068') is not null $$;
create or replace function ml_private.stage4_reactive_injury(s jsonb,hits jsonb) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(ml_private.stage3_task('gear-react',jsonb_build_object('actor',h->'target','data',jsonb_build_object('root',coalesce(s#>'{cardStack,stack,0,serial}',to_jsonb('batch'||(s->>'batch')))))) order by ord),'[]') from jsonb_array_elements(hits) with ordinality q(h,ord) where ml_private.stage4_on_board(s,(h->>'target')::int) and ml_private.stage4_combat_gear(s,(h->>'target')::int,'basic-068') is not null $$;
create or replace function ml_private.stage4_landing_tasks(s jsonb,a integer,direction text default null) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select case when ml_private.stage4_on_board(s,a) and ml_private.stage4_combat_gear(s,a,'basic-076') is not null then jsonb_build_array(ml_private.stage3_task('gear-push',jsonb_build_object('actor',a)||case when direction is null then '{}'::jsonb else jsonb_build_object('data',jsonb_build_object('direction',direction)) end)) else '[]'::jsonb end $$;
create or replace function ml_private.stage4_quiet_relocate(s jsonb,a integer,cell text,voluntary boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ begin s:=s||jsonb_build_object('_gearReactiveSkip',true);s:=ml_private.stage3_relocate(s,a,cell,voluntary,true);return s-'_gearReactiveSkip';end $$;
create or replace function ml_private.stage4_movement_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);action text:=t->>'action';key text;cells jsonb;card text;direction text:=t#>>'{data,direction}';region text;options jsonb:='{}';q jsonb;d text;cell text;target integer;begin
 if action='gear-react' then
  key:=(t#>>'{data,root}')||':guan:'||a;
  if not ml_private.stage4_on_board(s,a) or ml_private.stage4_combat_gear(s,a,'basic-068') is null or s#>>array['stage4','gearMarks',key]='true' or ml_private.stage3_mount_blocked(s,a) then return s||jsonb_build_object('_movementHandled',true);end if;
  select coalesce(jsonb_agg(v->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality c(v,ord) where ml_private.distance_for_version(s->>'version',s#>>array['players',a::text,'cell'],v->>'id')=1 and ml_private.stage4_board_empty(s,a,v->>'id',jsonb_build_array(a));
  if jsonb_array_length(cells)>0 then s:=jsonb_set(s,array['stage4','gearMarks',key],'true');s:=ml_private.select_choice(s,'gear-react',a,at,jsonb_build_object('cells',cells));end if;return s||jsonb_build_object('_movementHandled',true);
 elsif action='gear-push' then
  card:=ml_private.stage4_combat_gear(s,a,'basic-076');if not ml_private.stage4_on_board(s,a) or card is null then return s||jsonb_build_object('_movementHandled',true);end if;region:=ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region'];
  for q in select * from ml_private.arr(s->'players') loop target:=(q->>'seat')::int;if target=a or not ml_private.stage4_on_board(s,target) or ml_private.game_data(s,'map')#>>array[q->>'cell','region']<>region or not ml_private.stage4_gear_permitted(s,a,target,card) then continue;end if;
   for d in select v#>>'{}' from ml_private.arr(case when direction is not null then jsonb_build_array(direction) else '["up","right","down","left"]'::jsonb end) v loop cell:=ml_private.stage3_direction_cell(q->>'cell',d);if cell is not null and ml_private.stage4_board_empty(s,target,cell,jsonb_build_array(target)) then options:=options||jsonb_build_object(target||':'||d,jsonb_build_array(cell));end if;end loop;
  end loop;if options<>'{}'::jsonb then s:=ml_private.select_choice(s,'gear-push',a,at,jsonb_build_object('options',options));end if;return s||jsonb_build_object('_movementHandled',true);
 elsif action='board-desert' and coalesce(t#>>'{data,noTang}','false')<>'true' and ml_private.stage4_desert(s,a) is not null and ml_private.stage4_on_board(s,a) and ml_private.stage4_combat_gear(s,a,'basic-069') is not null then
  if ml_private.stage4_ignore_location(s,a) then s:=ml_private.emit(s,'terrain','S'||(a+1)||' 唐车忽略本次地形效果');else s:=ml_private.select_choice(s,'gear-terrain',a,at,jsonb_build_object('data',jsonb_build_object('task',t)));end if;return s||jsonb_build_object('_movementHandled',true);
 end if;return s||jsonb_build_object('_movementHandled',false);
end $$;
create or replace function ml_private.stage4_movement_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;t jsonb;cell text:=cmd->>'cell';target integer;card text;option text:=cmd->>'option';begin
 if c->>'kind'='gear-terrain' then
  if cmd->>'accept'='true' and not timeout and ml_private.stage4_combat_gear(s,a,'basic-069') is not null then return ml_private.emit(s,'terrain','S'||(a+1)||' 唐车忽略本次地形效果');end if;t:=c#>'{data,task}';t:=t||jsonb_build_object('data',coalesce(t->'data','{}')||jsonb_build_object('noTang',true));return ml_private.stage3_prepend(s,jsonb_build_array(t));
 end if;
 if timeout or not ml_private.stage4_on_board(s,a) then return s;end if;
 if c->>'kind'='gear-react' then
  if cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) and not ml_private.stage3_mount_blocked(s,a),'关烁落点不合法');s:=ml_private.stage4_quiet_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;
 end if;
 if option is not null and option<>'' then perform ml_private.need(c->'options' ? option,'临伟叶方向或目标不合法');target:=split_part(option,':',1)::int;cell:=c#>>array['options',option,'0'];card:=ml_private.stage4_combat_gear(s,a,'basic-076');perform ml_private.need(card is not null and ml_private.stage4_gear_permitted(s,a,target,card) and ml_private.stage4_board_empty(s,target,cell,jsonb_build_array(target)),'临伟叶落点已失效');s:=ml_private.stage4_quiet_relocate(s,target,cell,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;
end $$;
